//! The CraftCloud logo as the Windows executable's icon (craft-launcher does the same).

fn main() {
    // The icon is generated by `cargo xtask icons`.
    println!("cargo:rerun-if-changed=assets/craftcloud.ico");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        let mut res = winresource::WindowsResource::new();
        res.set_icon("assets/craftcloud.ico");
        res.set("ProductName", "CraftCloud");
        res.set("FileDescription", "CraftCloud");
        if let Err(e) = res.compile() {
            println!("cargo:warning=no icon in craftcloud.exe: {e}");
        }
    }
}
